def fail(message):
    print("ERROR:", message)
    sys.exit(1)

if not APP.exists():
    fail(f"Could not find {APP}")

try:
    branch = subprocess.check_output(
        ["git", "branch", "--show-current"],
        cwd=PROJECT_ROOT,
        text=True,
    ).strip()
except Exception as exc:
    fail(f"Could not verify Git branch: {exc}")

if branch != EXPECTED_BRANCH:
    fail(
        f"Safety stop: expected '{EXPECTED_BRANCH}' "
        f"but current branch is '{branch}'."
    )

